(()=>{'use strict';
const activities=[
 {id:'herbs',name:'Gather herbs',icon:'🌿',skill:'Foraging',desc:'A handful of useful weeds.',resource:'herbs',yield:1,xp:7,caption:'Your hero is contemplating a suspiciously leafy shrub.',quote:'“Ah yes, gathering herbs. The ancient art of standing near plants and calling it a career.”'},
 {id:'wood',name:'Chop wood',icon:'🪓',skill:'Woodcraft',desc:'Timber! Very satisfying.',resource:'wood',yield:1,xp:8,caption:'A tree has been asked politely to become firewood.',quote:'“The trees are nervous. Your hero has a tiny axe and absolutely no forestry license.”'},
 {id:'mine',name:'Mine ore',icon:'⛏️',skill:'Mining',desc:'Rock collection, but profitable.',resource:'ore',yield:1,xp:9,caption:'The rocks are putting up a brave, mostly geological, fight.',quote:'“You found a rock! It is worth money, unlike most rocks people find.”'},
 {id:'fish',name:'Go fishing',icon:'🎣',skill:'Fishing',desc:'Stare at water. Professionally.',resource:'fish',yield:1,xp:8,caption:'A fish has made a questionable life choice.',quote:'“Fishing: staring at water until lunch happens. Civilization is wonderful.”'},
 {id:'combat',name:'Fight monsters',icon:'⚔️',skill:'Combat',desc:'Battle monsters for loot and glory.',resource:null,yield:1,xp:12,caption:'A brave duel is underway. The monster seems mildly confused.',quote:'“The monster has been defeated. It was mostly slime and bad intentions.”'},
 {id:'pray',name:'Pray (ish)',icon:'🙏',skill:'Faith',desc:'Ask the cosmos for a favor.',resource:'favor',yield:1,xp:6,caption:'Your hero is negotiating with the infinite. Terms are vague.',quote:'“A prayer! I shall answer it after I finish this extremely important cloud.”'}
];
const resourcesDef=[['herbs','🌿','Herbs'],['wood','🪵','Wood'],['ore','🪨','Ore'],['fish','🐟','Fish'],['coins','🪙','Coins'],['favor','✨','Favor'],['essence','💧','Slime essence']];
const skillIcons={Foraging:'🌿',Woodcraft:'🪓',Mining:'⛏️',Fishing:'🎣',Combat:'⚔️',Faith:'🙏',Crafting:'🛠️'};
const quests=[['herbs','🌿','A modest pile of herbs',12],['wood','🪵','A tree-mendous effort',15],['ore','🪨','The motherlode-ish',12],['fish','🐟','Fish for compliments',10],['coins','🪙','A hero needs pocket money',30],['combat','⚔️','Slime happens',8]];
const monsters=[['Mossy Slime','🟢'],['Grumpy Goblin','👺'],['Cave Bat','🦇'],['Tiny Golem','🪨'],['Very Small Dragon','🐉']];
const fresh=()=>({resources:{herbs:0,wood:0,ore:0,fish:0,coins:0,favor:12,essence:0},skills:Object.fromEntries(Object.keys(skillIcons).map(k=>[k,0])),heroXP:0,activity:'herbs',paused:false,rate:1,bonus:1,questIndex:0,questProgress:0,heroName:'Pip',events:[],last:Date.now(),upgrades:{satchel:0,charm:0,sword:0},combat:{hp:30,maxHp:30,enemyHp:10,progress:0,kills:0,losses:0},crafts:{potions:0,swords:0,shields:0},gear:{weapon:0,armor:0}});
let s;try{s={...fresh(),...JSON.parse(localStorage.getItem('oddgods-save')||'{}')};let d=fresh();s.resources={...d.resources,...s.resources};s.skills={...d.skills,...s.skills};s.upgrades={...d.upgrades,...s.upgrades};s.combat={...d.combat,...s.combat};s.crafts={...d.crafts,...s.crafts};s.gear={...d.gear,...s.gear};}catch{s=fresh()}let toastTimer;
const fmt=n=>{if(n>=1e12)return (n/1e12).toFixed(2)+'T';if(n>=1e9)return (n/1e9).toFixed(2)+'B';if(n>=1e6)return (n/1e6).toFixed(2)+'M';if(n>=1e4)return (n/1e3).toFixed(1)+'K';return Math.floor(n).toLocaleString()};
const xpFor=l=>30*l*(l-1)/2+50*(l-1);const level=x=>{let l=1;while(x>=xpFor(l+1))l++;return l};
const toast=m=>{let e=document.querySelector('#toast');e.textContent=m;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),2500)};const current=()=>activities.find(a=>a.id===s.activity)||activities[0];
function log(text,icon='✨'){s.events.unshift({text,icon,time:Date.now()});s.events=s.events.slice(0,20)}
function questAction(id,amount){let q=quests[s.questIndex];if(id!==q[0])return;let progress=s.questProgress+amount;if(progress<q[3]){s.questProgress=progress;return}let rewardCount=0;while(progress>=q[3]&&id===quests[s.questIndex][0]){progress-=q[3];rewardCount++;s.questIndex=(s.questIndex+1)%quests.length;q=quests[s.questIndex];if(id!==q[0]){progress=0;break}}s.questProgress=progress;s.resources.coins+=rewardCount*10;s.resources.favor+=rewardCount*3;log(`Prophecy fulfilled! +${fmt(rewardCount*10)} coins and ${fmt(rewardCount*3)} favor.`,'📜');toast('Prophecy fulfilled! The gods are insufferably pleased.')}
function enemyMax(){return 10+Math.floor(s.combat.kills/5)*3+Math.floor(s.combat.kills/25)*10}
function heroMax(){return 30+Math.floor(level(s.skills.Combat||0)/2)*3+s.gear.armor*8}
function syncCombat(){s.combat.maxHp=heroMax();s.combat.hp=Math.min(s.combat.hp,s.combat.maxHp);s.combat.enemyHp=Math.max(1,Math.min(s.combat.enemyHp,enemyMax()))}
function monster(){return monsters[Math.min(monsters.length-1,Math.floor(s.combat.kills/5))]}
function winFight(){s.combat.kills++;let coins=3+Math.floor(s.combat.kills/3)+s.upgrades.sword*2;s.resources.coins+=coins;s.resources.essence+=1+Math.floor(s.combat.kills/10);questAction('combat',1);s.combat.enemyHp=enemyMax();s.combat.hp=Math.min(s.combat.maxHp,s.combat.hp+4+s.gear.armor);if(s.combat.kills===1||s.combat.kills%5===0)log(`${monster()[1]} Defeated a ${monster()[0]}! +${coins} coins and slime essence.`,'⚔️')}
function combatStep(){syncCombat();let hit=3+Math.floor(level(s.skills.Combat||0)/3)+s.upgrades.sword*2+s.gear.weapon*4;s.combat.enemyHp-=hit;if(s.combat.enemyHp<=0){winFight();return}let retaliate=Math.max(1,1+Math.floor(s.combat.kills/12)-s.gear.armor);s.combat.hp-=retaliate;if(s.combat.hp<=0){s.combat.losses++;s.combat.hp=Math.ceil(s.combat.maxHp*.55);s.combat.enemyHp=enemyMax();if(s.combat.losses===1||s.combat.losses%5===0)log('Your hero was dramatically bounced back to camp, but is already ready to try again.','💫')}}
function batchCombatSteps(steps){let precise=Math.min(steps,1200);for(let i=0;i<precise;i++)combatStep();let rest=steps-precise;if(rest>0){let avgHit=3+Math.floor(level(s.skills.Combat||0)/3)+s.upgrades.sword*2+s.gear.weapon*4;let approxKills=Math.floor(rest*avgHit/Math.max(1,enemyMax()));if(approxKills>0){s.combat.kills+=approxKills;s.resources.coins+=approxKills*(3+Math.floor(s.combat.kills/3)+s.upgrades.sword*2);s.resources.essence+=approxKills*(1+Math.floor(s.combat.kills/10));questAction('combat',approxKills);s.combat.enemyHp=enemyMax();}s.combat.hp=Math.max(1,Math.min(s.combat.maxHp,s.combat.hp+Math.floor(rest*.5)));}}
function act(id,count=1,manual=false){let a=activities.find(x=>x.id===id)||current();if(count<=0)return;let amount=count*a.yield*s.bonus*(a.id==='combat'?1+s.upgrades.sword*.5:1);if(a.id==='combat'){s.combat.progress+=count;let steps=Math.floor(s.combat.progress);s.combat.progress-=steps;if(steps)batchCombatSteps(steps);s.skills.Combat=(s.skills.Combat||0)+count*a.xp;s.heroXP+=count*(a.xp+2)}else{if(a.resource==='favor')s.resources.favor+=amount;else s.resources[a.resource]+=amount;questAction(a.id,amount);s.skills[a.skill]=(s.skills[a.skill]||0)+count*a.xp;s.heroXP+=count*(a.xp+2)}if(manual){log(`${a.icon} ${a.name}${a.id==='combat'?`: ${fmt(s.combat.kills)} monsters defeated`: `: +${fmt(amount)} ${a.resource==='favor'?'favor':a.resource}`}.`,a.icon);render()}}
function renderActivity(){document.querySelector('#activityGrid').innerHTML=activities.map(a=>`<button class="activity-btn ${s.activity===a.id?'selected':''}" data-act="${a.id}"><span class="activity-icon">${a.icon}</span><span class="activity-name">${a.name}</span><span class="activity-rate">${a.desc}</span></button>`).join('')}
function renderCombat(){syncCombat();let m=monster();document.querySelector('#combatStatus').innerHTML=`<div class="battle-head"><strong>⚔️ ${m[1]} ${m[0]}</strong><span>${fmt(s.combat.kills)} wins · ${fmt(s.combat.losses)} knockouts</span></div><div class="battle-bars"><div><small>MONSTER · ${fmt(s.combat.enemyHp)} / ${fmt(enemyMax())} HP</small><div class="battle-track monster-track"><i style="width:${Math.max(0,Math.min(100,s.combat.enemyHp/enemyMax()*100))}%"></i></div></div><div><small>HERO · ${fmt(s.combat.hp)} / ${fmt(s.combat.maxHp)} HP</small><div class="battle-track"><i style="width:${Math.max(0,Math.min(100,s.combat.hp/s.combat.maxHp*100))}%"></i></div></div></div>`}
function render(){const a=current();renderActivity();renderCombat();document.querySelector('#favor').textContent=fmt(s.resources.favor);document.querySelector('#currentActivity').textContent=s.paused?'Taking a little breather':a.name;document.querySelector('#activityIcon').textContent=s.paused?'💤':a.icon;document.querySelector('#rateLabel').textContent=s.paused?'0':(s.rate*(1+s.upgrades.charm*.25)).toFixed(1).replace(/\.0$/,'');document.querySelector('#sceneCaption').textContent=s.paused?'Your hero is resting. Even legends need a snack break.':a.id==='combat'?`${monster()[0]} faces your hero. ${fmt(s.combat.kills)} monsters defeated so far.`:a.caption;document.querySelector('#godQuote').textContent=s.paused?'“Finally, a moment of peace. I was getting tired of narrating.”':a.quote;document.querySelector('#pauseBtn').textContent=s.paused?'▶ Resume':'Ⅱ Pause';
 let lv=level(s.heroXP),prog=s.heroXP-xpFor(lv),need=xpFor(lv+1)-xpFor(lv);document.querySelector('#heroLevel').textContent=fmt(lv);document.querySelector('#xpLabel').textContent=`${fmt(prog)} / ${fmt(need)} XP`;document.querySelector('#heroXp').style.width=Math.min(100,prog/need*100)+'%';let q=quests[s.questIndex];document.querySelector('#questTitle').textContent=q[2];document.querySelector('#questProgress').textContent=`${fmt(s.questProgress)} / ${q[3]} ${q[0]==='combat'?'monsters':q[0]}`;document.querySelector('#questFill').style.width=Math.min(100,s.questProgress/q[3]*100)+'%';document.querySelector('#resources').innerHTML=resourcesDef.map(([k,i,n])=>`<div class="resource"><span class="resource-icon">${i}</span><strong>${fmt(s.resources[k]||0)}</strong><small>${n}</small></div>`).join('');document.querySelector('#skills').innerHTML=Object.entries(s.skills).map(([name,xp])=>{let l=level(xp),p=xp-xpFor(l),n=xpFor(l+1)-xpFor(l);return `<div class="skill-row"><span class="skill-emoji">${skillIcons[name]}</span><div class="skill-info"><strong>${name}</strong><div class="skill-bar"><i style="width:${Math.min(100,p/n*100)}%"></i></div></div><span class="skill-level">${fmt(l)}</span></div>`}).join('');document.querySelector('#skillNav').textContent=Object.keys(s.skills).length;document.querySelector('#eventLog').innerHTML=(s.events.length?s.events:[{text:'A new little legend begins. Your god is already taking credit.',icon:'🌟',time:Date.now()}]).slice(0,4).map(e=>`<div class="event-item"><b>${e.icon}</b><span>${e.text}</span><time>${ago(e.time)}</time></div>`).join('');document.querySelector('#topTab').textContent=(document.querySelector('.nav button.active')?.dataset.tab||'journey').toUpperCase()}
function ago(t){let n=Math.max(0,Math.floor((Date.now()-t)/1000));return n<60?'just now':n<3600?`${Math.floor(n/60)}m ago`:n<86400?`${Math.floor(n/3600)}h ago`:`${Math.floor(n/86400)}d ago`}
function save(){s.last=Date.now();localStorage.setItem('oddgods-save',JSON.stringify(s));document.querySelector('#saveStatus').textContent='All progress saved'}function offline(){let seconds=Math.max(0,(Date.now()-s.last)/1000);if(seconds>2&&!s.paused){let a=current(),actions=seconds*s.rate*(1+s.upgrades.charm*.25);act(s.activity,actions);log(`While you were away: ${fmt(actions)} ${a.name.toLowerCase()} actions.`, '⏳');toast(`Welcome back! ${fmt(actions)} idle actions happened while you were away.`)}s.last=Date.now()}
const upgrades=[{id:'satchel',name:'Bottomless-ish satchel',icon:'🎒',cost:{wood:15,herbs:10},desc:'Gather 25% more from every action.'},{id:'charm',name:'Suspiciously lucky charm',icon:'🍀',cost:{coins:50,ore:5},desc:'Idle actions happen 25% faster.'},{id:'sword',name:'Sword with a point',icon:'🗡️',cost:{ore:12,coins:35},desc:'Combat hits harder and earns extra coins.'}];
const recipes=[{id:'potions',name:'Mossberry tonic',icon:'🧪',desc:'Restore 20 hero HP. A little herbal, a little suspicious.',cost:{herbs:3,fish:1},xp:18,min:1},{id:'swords',name:'Ironwood blade',icon:'🗡️',desc:'Equip automatically; +4 damage per strike.',cost:{ore:8,wood:5,coins:20},xp:35,min:2},{id:'shields',name:'Scrapwood shield',icon:'🛡️',desc:'Equip automatically; +8 max HP and reduce incoming damage.',cost:{wood:10,ore:4},xp:28,min:2}];
function costText(cost){return Object.entries(cost).map(([k,v])=>`${resourcesDef.find(x=>x[0]===k)?.[1]||'🪨'} ${v}`).join(' + ')}
function openModal(type){let title,body;if(type==='skills'){title='Skills & divine upgrades';body=`<p>Practice makes proficient. Proficient makes the gods look good. Spend your hard-earned loot on a small advantage.</p><div class="modal-list">${Object.entries(s.skills).map(([n,x])=>`<div class="modal-row"><span>${skillIcons[n]}</span><span>${n}</span><b>Level ${fmt(level(x))} · ${fmt(x)} XP</b></div>`).join('')}</div><h3 class="modal-subhead">A few questionable purchases</h3><div class="modal-list">${upgrades.map(u=>{let owned=s.upgrades[u.id];return `<div class="modal-row"><span>${u.icon}</span><span><b>${u.name}</b><br><small>${u.desc}</small><br><small>${costText(u.cost)}${owned?' · owned ×'+owned:''}</small></span><button class="buy" data-buy="${u.id}" ${Object.entries(u.cost).some(([k,v])=>s.resources[k]<v)?'disabled':''}>Buy</button></div>`}).join('')}</div>`}else if(type==='crafting'){title='Workshop of questionable genius';body=`<p>Turn gathered materials into useful gear. Equipment auto-equips when crafted; tonics can be used whenever your hero needs a little less dying.</p><div class="craft-summary">🛠️ Crafting level ${level(s.skills.Crafting)} <span>·</span> 🧪 Tonics ${fmt(s.crafts.potions)} <span>·</span> 🗡️ Blades ${fmt(s.crafts.swords)} <span>·</span> 🛡️ Shields ${fmt(s.crafts.shields)}</div><div class="modal-list">${recipes.map(r=>{let locked=level(s.skills.Crafting)<r.min,poor=Object.entries(r.cost).some(([k,v])=>s.resources[k]<v);return `<div class="modal-row recipe-row"><span>${r.icon}</span><span><b>${r.name}</b><br><small>${r.desc}</small><br><small>Cost: ${costText(r.cost)} · ${r.xp} crafting XP · ${locked?`Unlocks at level ${r.min}`:'Ready'}</small></span><button class="buy" data-craft="${r.id}" ${locked||poor?'disabled':''}>Craft</button></div>`}).join('')}</div><div class="equipment-note">Equipped: ⚔️ ${s.gear.weapon?'Ironwood blade':'bare hands'} · 🛡️ ${s.gear.armor?'Scrapwood shield':'hope and optimism'}</div><div class="modal-list"><div class="modal-row"><span>🧪</span><span>Use Mossberry tonic · restore 20 HP</span><b>${fmt(s.crafts.potions)} available</b><button class="buy" data-use-potion ${s.crafts.potions<1||s.combat.hp>=s.combat.maxHp?'disabled':''}>Use</button></div></div>`}else if(type==='quests'){title='Prophecies, allegedly';body=`<p>Your god has a plan. The plan is mostly collecting things and being paid in pocket change.</p><div class="modal-list">${quests.map((q,i)=>`<div class="modal-row"><span>${q[1]}</span><span>${q[2]}${i===s.questIndex?' · <b>ACTIVE</b>':''}</span><b>${i===s.questIndex?fmt(s.questProgress):'—'} / ${q[3]}</b></div>`).join('')}</div><p>Complete prophecies for coins and divine favor. They keep coming forever. Much like the universe.</p>`}else if(type==='log'){title='The Chronicle';body=`<p>A painstakingly accurate account of your hero’s increasingly improbable career.</p><div class="modal-list">${(s.events.length?s.events:[{text:'Nothing yet. The page is judging you silently.',icon:'📖',time:Date.now()}]).map(e=>`<div class="modal-row"><span>${e.icon}</span><span>${e.text}</span><b>${ago(e.time)}</b></div>`).join('')}</div>`}else{title='Pocket universe';body=`<p>Everything acquired while being heroically present.</p><div class="resource-list modal-resources">${resourcesDef.map(([k,i,n])=>`<div class="resource"><span class="resource-icon">${i}</span><strong>${fmt(s.resources[k]||0)}</strong><small>${n}</small></div>`).join('')}</div><div class="modal-row"><span>⚔️</span><span>Monsters defeated</span><b>${fmt(s.combat.kills)}</b></div>`}
document.querySelector('#modalContent').innerHTML=`<div class="eyebrow">ODDLY USEFUL INFORMATION</div><h2>${title}</h2>${body}`;document.querySelector('#modal').hidden=false;document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>buy(b.dataset.buy));document.querySelectorAll('[data-craft]').forEach(b=>b.onclick=()=>craft(b.dataset.craft));document.querySelector('[data-use-potion]')?.addEventListener('click',usePotion)}
function buy(id){let u=upgrades.find(x=>x.id===id);if(!u||Object.entries(u.cost).some(([k,v])=>s.resources[k]<v)){toast('Not quite enough supplies, brave shopper.');return}Object.entries(u.cost).forEach(([k,v])=>s.resources[k]-=v);s.upgrades[id]++;if(id==='satchel')s.bonus+=.25;log(`${u.icon} Bought ${u.name}. Your god approves (of the transaction).`,u.icon);toast(`${u.name} acquired!`);openModal('skills');render();save()}
function craft(id){let r=recipes.find(x=>x.id===id);if(!r)return;if(level(s.skills.Crafting)<r.min||Object.entries(r.cost).some(([k,v])=>s.resources[k]<v)){toast('The workshop needs more materials or practice.');return}Object.entries(r.cost).forEach(([k,v])=>s.resources[k]-=v);s.crafts[r.id]++;if(id==='swords')s.gear.weapon++;if(id==='shields')s.gear.armor++;s.skills.Crafting+=r.xp;s.heroXP+=Math.floor(r.xp/2);syncCombat();log(`${r.icon} Crafted ${r.name}${id==='potions'?'.':'; better things are now equipped!'}`,r.icon);toast(`${r.name} crafted!`);render();save();openModal('crafting')}
function usePotion(){if(s.crafts.potions<1||s.combat.hp>=s.combat.maxHp)return;s.crafts.potions--;let healed=Math.min(20,s.combat.maxHp-s.combat.hp);s.combat.hp+=healed;toast(`Mossberry tonic restored ${healed} HP.`);render();save();openModal('crafting')}
document.querySelector('#activityGrid').addEventListener('click',e=>{let b=e.target.closest('[data-act]');if(b){let changed=s.activity!==b.dataset.act;s.activity=b.dataset.act;if(changed){log(`${current().icon} Set off to ${current().name.toLowerCase()}.`,current().icon);toast(`${current().name} — away we go!`)}act(s.activity,1,true)}});
document.querySelector('#pauseBtn').onclick=()=>{s.paused=!s.paused;log(s.paused?'Your hero decided to rest.':'Your hero is back at it.','💤');render();save()};document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openModal(b.dataset.open));document.querySelector('#craftButton').onclick=()=>openModal('crafting');document.querySelector('#questButton').onclick=()=>openModal('quests');document.querySelector('#inventoryBtn').onclick=()=>openModal('inventory');document.querySelector('#closeModal').onclick=()=>document.querySelector('#modal').hidden=true;document.querySelector('#modal').onclick=e=>{if(e.target.id==='modal')e.currentTarget.hidden=true};document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('active',x===b));let tab=b.dataset.tab;if(tab!=='journey')openModal(tab);render()});document.querySelector('#resetBtn').onclick=()=>{if(confirm('Start a fresh little universe? This erases the save on this device.')){localStorage.removeItem('oddgods-save');s=fresh();render();save();toast('A new universe. Same questionable gods.')}};
offline();render();let lastFrame=Date.now();setInterval(()=>{let now=Date.now(),dt=Math.max(0,(now-lastFrame)/1000);lastFrame=now;if(!s.paused){act(s.activity,dt*s.rate*(1+s.upgrades.charm*.25));s.last=now}render();save()},1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden){offline();render()}});
})();

