30: function renderCombat(){syncCombat();let m=monster();document.querySelector('#combatStatus').innerHTML=`<div class="battle-head"><strong>⚔️ ${m[1]} ${m[0]}</strong><span>${fmt(s.combat.kills)} wins · ${fmt(s.combat.losses)} knockouts</span></div><div class="battle-bars"><div><small>MONSTER · ${fmt(s.combat.enemyHp)} / ${fmt(enemyMax())} HP</small><div class="battle-track monster-track"><i style="width:${Math.max(0,Math.min(100,s.combat.enemyHp/enemyMax()*100))}%"></i></div></div><div><small>HERO · ${fmt(s.combat.hp)} / ${fmt(s.combat.maxHp)} HP</small><div class="battle-track"><i style="width:${Math.max(0,Math.min(100,s.combat.hp/s.combat.maxHp*100))}%"></i></div></div></div>`}
