40: function act(id,count=1,manual=false){let a=activities.find(x=>x.id===id)||current();if(count<=0)return;let amount=count*a.yield*s.bonus*(a.id==='combat'?1+s.upgrades.sword*.5:1);if(a.id==='combat'){s.combat.progress+=count;let steps=Math.floor(s.combat.progress);s.combat.progress-=steps;if(steps)batchCombatSteps(steps);s.skills.Combat=(s.skills.Combat||0)+count*a.xp;s.heroXP+=count*(a.xp+2)}else{if(a.resource==='favor')s.resources.favor+=amount;else s.resources[a.resource]+=amount;questAction(a.id,amount);s.skills[a.skill]=(s.skills[a.skill]||0)+count*a.xp;s.heroXP+=count*(a.xp+2)}if(manual){log(`${a.icon} ${a.name}${a.id==='combat'?`: ${fmt(s.combat.kills)} monsters defeated`: `: +${fmt(amount)} ${a.resource==='favor'?'favor':a.resource}`}.`,a.icon);render()}}
